do $$ begin
if exists(select 1 from artists where code='ART-KOWHAI') then return; end if;
select 'SH-NORTH','Northern autumn show',a.id,p.id,v.id,(current_date+7+time '19:00') at time zone 'Pacific/Auckland',(current_date+7+time '21:00') at time zone 'Pacific/Auckland',current_date-2,'confirmed','NZD',500000,150000,current_date-3,'Mara','contracts/north-signed.pdf',current_date-10,'Mara' from artists a,promoters p,venues v where a.code='ART-KOWHAI' and p.code='PRO-NORTH' and v.code='VEN-HARBOUR';
select 'SH-CLASH','River hold',a.id,p.id,v.id,(current_date+7+time '20:00') at time zone 'Pacific/Auckland',(current_date+7+time '22:00') at time zone 'Pacific/Auckland',current_date-1,'hold',420000,100000,current_date+2,'Tane' from artists a,promoters p,venues v where a.code='ART-KOWHAI' and p.code='PRO-SOUTH' and v.code='VEN-RIVER';
select 'SH-SYDNEY','Harbour Lights Sydney',a.id,p.id,v.id,(current_date+12+time '20:00') at time zone 'Australia/Sydney',(current_date+12+time '22:00') at time zone 'Australia/Sydney',current_date+2,'confirmed','AUD',600000,200000,current_date+2,'Mara','contracts/sydney-signed.pdf',current_date-5,'Mara' from artists a,promoters p,venues v where a.code='ART-HARBOUR' and p.code='PRO-NORTH' and v.code='VEN-SYDNEY';
select 'SH-READY','Small room confirmed',a.id,p.id,v.id,(current_date+2+time '18:00') at time zone 'Pacific/Auckland',(current_date+2+time '19:00') at time zone 'Pacific/Auckland',current_date+1,'hold',100000,'Tane' from artists a,promoters p,venues v where a.code='ART-KOWHAI-DUO' and p.code='PRO-NORTH' and v.code='VEN-RIVER';
end $$;
